CREATE TABLE IF NOT EXISTS "public"."line_item" (
  "id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "invoice_id" integer NOT NULL REFERENCES "public"."invoice"("id") ON DELETE CASCADE,
